import type { Type } from '@angular/core';
import {
  LucideCalendar,
  LucideCalendarRange,
  LucideCar,
  LucideCarFront,
  LucideHash,
  LucideIdCard,
  LucideMapPin,
  LucidePencilLine,
  LucideRectangleHorizontal,
  LucideUser,
} from '@lucide/angular';
import type { FieldConfig } from './field-config.model';

/**
 * The icon of a step 1 field, chosen by its key (ADR-0010 section 7): a presentation map, no
 * behaviour or copy depends on it. Any other key of a text, number, select or date field gets the
 * default; a checkbox gets none.
 */
const BY_KEY: Record<string, Type<unknown>> = {
  documentType: LucideIdCard,
  documentNumber: LucideHash,
  fullName: LucideUser,
  birthDate: LucideCalendar,
  city: LucideMapPin,
  plate: LucideRectangleHorizontal,
  make: LucideCar,
  model: LucideCarFront,
  vehicleYear: LucideCalendarRange,
};

export function iconForField(config: Pick<FieldConfig, 'key' | 'type'>): Type<unknown> | null {
  if (config.type === 'checkbox') return null;
  return Object.hasOwn(BY_KEY, config.key) ? BY_KEY[config.key] : LucidePencilLine;
}
const BULLET = '•';
const ALNUM = /[\p{L}\p{N}]/u;
const MAX_VISIBLE = 4;

export interface MaskedDocument {
  /** The value with every hidden letter or digit replaced by a bullet. */
  text: string;
  /** What a screen reader gets instead of the masked string. */
  accessibleText: string;
}

/**
 * Partial masking of the document number (US-03-BR-02): with n letters and digits, the last
 * k = min(4, floor(n / 2)) stay visible; every earlier one becomes a bullet; separators stay in
 * place. One rule for every country, no country branch.
 */
export function maskDocumentNumber(value: string): MaskedDocument {
  const chars = Array.from(value);
  const total = chars.filter((c) => ALNUM.test(c)).length;
  const visible = Math.min(MAX_VISIBLE, Math.floor(total / 2));
  const hiddenCount = total - visible;
  let seen = 0;
  let firstVisible = chars.length;
  const masked = chars.map((c, index) => {
    if (!ALNUM.test(c)) return c;
    seen++;
    if (seen <= hiddenCount) return BULLET;
    if (firstVisible === chars.length) firstVisible = index;
    return c;
  });
  const tail = visible > 0 ? chars.slice(firstVisible).join('') : '';
  return {
    text: masked.join(''),
    accessibleText: tail === '' ? 'Número oculto' : `Número oculto, termina en ${tail}`,
  };
}
